{"refs":["lines","shipping","tax_percent"],"code":"from fractions import Fraction

def _rounded(value):
    return (2 * value.numerator + value.denominator) // (2 * value.denominator)

def solve(facts):
    subtotal = 0
    for line in facts["lines"]:
        discount = Fraction(line["discount_percent"])
        amount = line["qty"] * line["unit_cents"] * (1 - discount / 100)
        subtotal += _rounded(amount)
    tax = _rounded(Fraction(facts["tax_percent"]) * subtotal / 100)
    return {"subtotal_cents": subtotal, "tax_cents": tax, "total_cents": subtotal + tax + facts["shipping"]}

def check(answer, facts):
    subtotal = 0
    for line in facts["lines"]:
        percent = Fraction(line["discount_percent"])
        numerator = line["qty"] * line["unit_cents"] * (100 * percent.denominator - percent.numerator)
        denominator = 100 * percent.denominator
        subtotal += (2 * numerator + denominator) // (2 * denominator)
    tax_percent = Fraction(facts["tax_percent"])
    numerator = subtotal * tax_percent.numerator
    denominator = 100 * tax_percent.denominator
    tax = (2 * numerator + denominator) // (2 * denominator)
    return answer == {"subtotal_cents": subtotal, "tax_cents": tax, "total_cents": subtotal + tax + facts["shipping"]}"}

